# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
import torch
import triton
import triton.language as tl


# MODE encoding:
#   2 -> p=2   (L2: sqrt(sum(x^2)))
#   1 -> p=1   (L1: sum(|x|))
#   0 -> p=0   (count non-zero)
#   3 -> p=inf (max |x|)
#   4 -> p=-inf(min |x|)
#   5 -> general p: (sum |x|^p)^(1/p)
#
# Single contiguous last-dim reduction kernel. Input is viewed as (M, N) with
# stride 1 along the reduction axis. Per-chunk tree-ordered partials are summed
# into a 1D accumulator, which is numerically much safer than a serial loop.
@triton.jit
def _norm_lastdim_kernel(
    x_ptr,
    out_ptr,
    M,
    N,
    p,  # fp32 scalar: general-p exponent
    pinv,  # fp32 scalar: 1/p
    MODE: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
):
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    n_blocks = (M + BLOCK_M - 1) // BLOCK_M

    for rb in range(pid, n_blocks, nprog):
        rows = rb * BLOCK_M + tl.arange(0, BLOCK_M)
        row_mask = rows < M

        if MODE == 3:
            acc = tl.zeros([BLOCK_M], dtype=tl.float32)
        elif MODE == 4:
            acc = tl.full([BLOCK_M], float("inf"), dtype=tl.float32)
        else:
            acc = tl.zeros([BLOCK_M], dtype=tl.float32)

        for off in range(0, N, BLOCK_N):
            cols = off + tl.arange(0, BLOCK_N)
            mask = row_mask[:, None] & (cols < N)[None, :]
            if MODE == 4:
                a = tl.load(
                    x_ptr + rows[:, None] * N + cols[None, :],
                    mask=mask,
                    other=float("inf"),
                ).to(tl.float32)
            else:
                a = tl.load(
                    x_ptr + rows[:, None] * N + cols[None, :],
                    mask=mask,
                    other=0.0,
                ).to(tl.float32)
            aa = tl.abs(a)
            if MODE == 2:
                acc += tl.sum(aa * aa, axis=1)
            elif MODE == 1:
                acc += tl.sum(aa, axis=1)
            elif MODE == 0:
                acc += tl.sum((aa != 0.0).to(tl.float32), axis=1)
            elif MODE == 3:
                acc = tl.maximum(acc, tl.max(aa, axis=1))
            elif MODE == 4:
                acc = tl.minimum(acc, tl.min(aa, axis=1))
            else:
                acc += tl.sum(tl.extra.ascend.libdevice.pow(aa, p), axis=1)

        if MODE == 2:
            res = tl.sqrt(acc)
        elif MODE == 1 or MODE == 0 or MODE == 3 or MODE == 4:
            res = acc
        else:
            res = tl.extra.ascend.libdevice.pow(tl.abs(acc), pinv)

        tl.store(out_ptr + rows, res.to(out_ptr.dtype.element_ty), mask=row_mask)


def _mode_for(p):
    pf = float(p)
    if pf == 2.0:
        return 2
    if pf == 1.0:
        return 1
    if pf == 0.0:
        return 0
    if pf == float("inf"):
        return 3
    if pf == float("-inf"):
        return 4
    return 5


def _blocks(M, N):
    # Keep the BLOCK_M * BLOCK_N tile well under the Ascend UB budget while
    # using a large BLOCK_N for large-N correctness cases so that per-chunk
    # tree-ordered partials stay numerically close to the fp64 reference.
    if N >= 2048 and M < 1024:
        return (4, 2048)
    if N >= 512:
        if M >= 32768:
            # Large-M row reductions (e.g. 64x512x512 -> M=32768) are launch-
            # bound at a 4096-program grid. A 64x256 tile cuts the grid to 512
            # programs while keeping 2 x 64x256 fp32 live tensors inside the
            # Ascend UB budget (no 64x512 tile, which would overflow).
            return (64, 256)
        return (8, 512)
    if N >= 128:
        return (8, 256)
    return (8, 128)


def _lastdim_norm(x, N, out, pf, pinv, mode):
    M = x.numel() // N
    if M == 0:
        return out
    BLOCK_M, BLOCK_N = _blocks(M, N)
    grid = (min(triton.cdiv(M, BLOCK_M), 4096),)
    _norm_lastdim_kernel[grid](
        x,
        out,
        M,
        N,
        pf,
        pinv,
        MODE=mode,
        BLOCK_M=BLOCK_M,
        BLOCK_N=BLOCK_N,
    )
    return out


def norm_scalaropt_dim(x, p, dim, keepdim=False):
    x = x.contiguous()
    ndim = x.dim()

    # Normalize dims (int or sequence) to a list of non-negative dims.
    if isinstance(dim, (list, tuple)):
        dims = [d % ndim for d in dim]
        dims = sorted(set(dims), reverse=True)
    else:
        dims = [dim % ndim]

    if len(dims) == 0:
        return x.clone()

    out_shape = list(x.shape)
    for d in dims:
        if keepdim:
            out_shape[d] = 1
        else:
            out_shape.pop(d)

    if x.numel() == 0:
        return torch.empty(out_shape, device=x.device, dtype=x.dtype)

    mode = _mode_for(p)
    pf = float(p)
    pinv = 0.0 if mode != 5 else 1.0 / pf

    # Single-axis reduction.
    if len(dims) == 1:
        d = dims[0]
        N = x.shape[d]
        if x.stride(d) == 1:
            # Already contiguous along the reduction axis.
            out = torch.empty(out_shape, device=x.device, dtype=x.dtype)
            return _lastdim_norm(x, N, out, pf, pinv, mode)

        # Route a non-last-dim reduction into the contiguous last-dim kernel via
        # a permute + contiguous materialization. This keeps the reduction
        # tree-ordered and avoids an uncoalesced strided kernel.
        perm = [i for i in range(ndim) if i != d] + [d]
        xp = x.permute(perm).contiguous()
        out_p = torch.empty(xp.shape[:-1], device=x.device, dtype=x.dtype)
        _lastdim_norm(xp, N, out_p, pf, pinv, mode)
        if keepdim:
            return out_p.unsqueeze(d)
        return out_p

    # Multi-axis reduction: compose nested single-axis norms in descending dim
    # order. Intermediate results stay in fp32 (single accumulation rounding
    # boundary, matching the reference) and are cast once at the very end.
    src_dtype = x.dtype
    cur = x.to(torch.float32) if src_dtype != torch.float32 else x
    cur_p = p
    for d in dims:
        cur = norm_scalaropt_dim(cur, cur_p, d, keepdim=True)
        if float(cur_p) == 0.0:
            cur_p = 1
    if not keepdim:
        cur = cur.reshape(out_shape)
    if src_dtype != torch.float32:
        cur = cur.to(src_dtype)
    return cur
